enum DataId {
    D_NETGAME = 0,     // nonzero in a net game (the level loop's test)
    D_OBJ_COUNT = 1,     // the level's object count
    D_OBJ_TABLE = 2,     // the pointer to the objects (0xB4 bytes each)
    D_OBJ_TYPES = 3,     // the pointer to the level's object types (0x244 bytes each)
    D_NEAR_COUNT = 4,     // the count of the objects near enough to be updated this frame
    D_NEAR_LIST = 5,     // their pointers
    D_PROJECTILES = 6,     // the projectiles (0x5C bytes each, 256: the player's first 128)
    D_DRAW_COUNT = 7,     // the frame's draw list's length
    D_FRAME_TIME = 8,     // the last frame's time (16.16 seconds)
    D_PLAYER_POS = 9,     // the player's ship: x, y, z, then three angles
    D_PLAYER_VEL = 10,     // its velocity, x y z
    D_PLAYER_SPIN = 11,     // its angles' rates
    D_PLAYER_SHIELD = 12,     // its shield (0x10000 full)
    D_PLAYER_X4 = 13,     // a fourth word the report carries (0x10000 at a net level's start)
    D_SHIP_MODEL = 14,     // the player's ship's model (ship.bin)
    D_KEY_TABLE = 15,     // the keys down, a byte by scan code
    D_BURN_KEY = 16,     // the afterburner's key (a scan code; VOX.INI's weaponKey, 56 Left Alt)
    D_FIRE_KEY = 17,     // the fire key (57 Space)
    D_BURN_FUEL = 18,     // the afterburner's fuel (0 at the start; a pickup or TRIBURN gives some)
    D_LOCAL_SPIN = 19,     // the ship's turn rates about its own axes (the stick's and keys' doing)
    D_ATTITUDE = 20,     // the ship's attitude: a word, then a 3x3 float matrix (columns its right, up, forward)
    D_DIFFICULTY = 21,     // the difficulty (0..3, Easy..Terminal)
    D_LEVEL_DONE = 22,     // the level done: set, the level loop ends at the frame's end as completed (alive)
    D_POD_TABLE = 23,     // the archives' table the model loader looks a name up in
    D_LEVEL_INDEX = 24,     // the campaign's level, 0..
    D_LEVEL_COUNT = 25,     // the campaign's level count
    D_LEVEL_NAMES = 26,     // the levels' file names, 0x28 bytes each
    D_COUNT = 27
};
